window.FILM_WORK_PROMPTS={"work_id":"src-3327dfdd7035c32f","records":[{"work_id":"src-3327dfdd7035c32f","frame_id":"FG-a6e420a445fd6ad0","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (643).jpg","source_page":"https://film-grab.com/2015/10/08/mad-max-2/","scene":"一只灰褐色斑纹犬坐在车内，嘴里横咬着一根浅色骨头，颈部系着红色布带。左侧前景是深色方向盘，背景为明亮的天空与车窗外景。","analysis":"画面采用近景构图，主体为犬只头部及上半身，占据画面右侧约三分之一区域。左侧前景为深色方向盘，占据约四分之一画面，形成前景遮挡。光线从背景透入，形成逆光效果，使犬只轮廓清晰，面部处于阴影中，但眼睛和骨头受光明显。色彩以冷调的灰蓝天空与暖调的犬毛、骨头形成对比，红色布带在暗部中较为醒目。","prompt":"一只灰褐色斑纹犬坐在车内，头部及上半身可见，嘴里横咬着一根浅色骨头，颈部系着红色布带。左侧前景是深色方向盘，占据画面左侧，形成遮挡。背景是明亮的淡蓝色天空，光线从后方透入，形成逆光效果，使犬只轮廓清晰，面部处于阴影中，但眼睛和骨头受光明显。色彩以冷调的灰蓝天空与暖调的犬毛、骨头形成对比，红色布带在暗部中较为醒目。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T02:32:20-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (643).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.5,"observed_resolution":"normal","observation_limits":[],"id":"VP-59170ad0d3765519","origin":"visual"},{"work_id":"src-3327dfdd7035c32f","frame_id":"FG-64447d76ac7effb9","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/18 (657).jpg","source_page":"https://film-grab.com/2015/10/08/mad-max-2/","scene":"长发少年上半身位于画面中央，身穿粗糙无袖衣物，背景是多云天空、破旧的木桩围栏和铁丝网，地面呈红褐色。","analysis":"人物占据画面中心约三分之一，仅上半身可见，头部微侧，视线偏向画面左侧。背景天空云层厚重，光线柔和漫射，无明显硬阴影。人物面部与衣物受光均匀，色调偏暖黄与灰褐。木桩与铁丝网在人物身后横向延伸，形成空间层次。","prompt":"长发少年上半身位于画面中央，头发凌乱，身穿粗糙无袖衣物，衣物边缘磨损。背景是多云天空，云层厚重，光线柔和漫射。人物身后有破旧的木桩围栏和铁丝网，木桩呈深褐色，铁丝网横向延伸。地面呈红褐色，远处有模糊的土坡。人物面部受光均匀，色调偏暖黄与灰褐，视线偏向画面左侧，表情严肃。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T02:32:27-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/18 (657).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.498,"observed_resolution":"normal","observation_limits":[],"id":"VP-51feae11310455c0","origin":"visual"},{"work_id":"src-3327dfdd7035c32f","frame_id":"FG-24ecf097f683a96d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/29 (656).jpg","source_page":"https://film-grab.com/2015/10/08/mad-max-2/","scene":"一架深色直升机悬浮在广阔的天空中，周围是大片层叠的灰白色积云，云层间透出淡蓝色的天光，整体氛围宁静而空旷。","analysis":"画面采用极简构图，直升机位于画面中下方，在巨大的天空背景下显得极其微小，强调了环境的辽阔。天空占据画面绝大部分，云层呈现出柔和的灰白色调，局部透出淡蓝色。光线均匀柔和，没有强烈的明暗对比，色彩层次丰富，从云层的亮白到天空的淡蓝过渡自然。","prompt":"这是一张写实风格的摄影作品，画面主体是一架深色的直升机，它位于画面中下方，在广阔的天空中显得非常渺小。直升机呈水平飞行姿态，轮廓清晰但细节因距离而模糊。背景是占据画面绝大部分的天空，布满了层层叠叠的灰白色积云，云层厚重且纹理丰富，部分区域透出淡蓝色的天光。整体光线柔和均匀，色彩以冷色调的蓝白为主，营造出一种宁静、空旷且略带压抑的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T02:32:34-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/29 (656).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.508,"observed_resolution":"normal","observation_limits":[],"id":"VP-e4dcabfde75b3732","origin":"visual"},{"work_id":"src-3327dfdd7035c32f","frame_id":"FG-146fbddbf01ef19a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/39 (653).jpg","source_page":"https://film-grab.com/2015/10/08/mad-max-2/","scene":"黄昏时分的广阔荒漠地平线，天空呈现橙红至紫红的渐变色彩，云层厚重。画面右侧地平线上有一辆深色越野车的剪影，车身轮廓清晰，周围是平坦无垠的暗色地面。","analysis":"构图采用横向宽幅比例，地平线位于画面下方约三分之一处，大面积留白给天空。车辆位于右侧，呈侧面剪影，相对于广阔背景显得渺小。光线来自地平线方向，形成强烈的逆光效果，使地面和车辆完全处于阴影中。天空色彩层次丰富，从底部的暖橙色过渡到顶部的紫红色，云层纹理细腻。","prompt":"黄昏时分的广阔荒漠地平线，天空呈现橙红至紫红的渐变色彩，云层厚重。画面右侧地平线上有一辆深色越野车的剪影，车身轮廓清晰，周围是平坦无垠的暗色地面。构图采用横向宽幅比例，地平线位于画面下方约三分之一处，大面积留白给天空。车辆位于右侧，呈侧面剪影，相对于广阔背景显得渺小。光线来自地平线方向，形成强烈的逆光效果，使地面和车辆完全处于阴影中。天空色彩层次丰富，从底部的暖橙色过渡到顶部的紫红色，云层纹理细腻。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T02:32:42-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/39 (653).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.515,"observed_resolution":"normal","observation_limits":[],"id":"VP-d4fc93d080557214","origin":"visual"},{"work_id":"src-3327dfdd7035c32f","frame_id":"FG-2cfedbe681846bd9","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/50 (628).jpg","source_page":"https://film-grab.com/2015/10/08/mad-max-2/","scene":"荒漠平原上，一架直升机悬停于画面中央，左侧公路排列着车辆，下方地面有车辆扬起尘土，天空占据上方三分之一。","analysis":"采用高角度俯视构图，地平线位于画面上方三分之一处。直升机位于视觉中心，旋翼呈现动态模糊。左侧公路呈对角线延伸，车辆沿路排列。下方地面车辆扬起明显的黄褐色尘土。光线为强烈的自然日光，阴影短促，色彩以土黄、灰褐和淡蓝为主，明暗对比清晰。","prompt":"高角度俯视镜头，展现广阔荒凉的荒漠平原。画面中央，一架深色直升机悬停在空中，旋翼因高速旋转呈现模糊的白色线条。左侧一条灰白色公路斜向延伸至远方，路面上排列着数辆深色车辆。直升机下方的红褐色土地上，几辆车辆正在行驶，车轮卷起明显的黄褐色尘土带。地面覆盖着稀疏的灰绿色低矮植被，纹理粗糙。上方是纯净的淡蓝色天空，地平线平直清晰。强烈的日光照射下，物体投射出短促的阴影，整体色调呈现干燥的土黄色与冷调天空的对比。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T02:32:49-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/50 (628).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.517,"observed_resolution":"normal","observation_limits":[],"id":"VP-5d940cfa40111086","origin":"visual"},{"work_id":"src-3327dfdd7035c32f","frame_id":"FG-5e98195b0c40c5a4","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/06 (643).jpg","source_page":"https://film-grab.com/2015/10/08/mad-max-2/","scene":"画面主体为车辆底盘下方的机械结构，可见生锈的金属板、圆柱形电机部件及红色线缆。一只人手从右侧伸入，手指按在金属构件上，周围是昏暗的泥土色环境。","analysis":"构图采用仰视视角，聚焦于狭窄的机械空间内部。画面右侧可见一只人手，手指弯曲按在金属边缘，仅露出手部及部分前臂，身体其余部分不可见。光线从上方或侧面射入，照亮了金属部件的纹理和手背，形成明暗对比。色彩以铁锈红、深灰和土黄为主，质感粗糙，充满工业气息。","prompt":"仰视视角拍摄车辆底盘下方的狭窄空间，画面中心是复杂的机械结构，包括生锈的金属板、圆柱形电机部件和连接的红色线缆。右侧一只人手伸入画面，手指按在金属构件上，皮肤纹理清晰。环境昏暗，光线从上方射入，照亮了金属表面的锈迹和手背，形成强烈的明暗对比。色彩以铁锈红、深灰和土黄为主，质感粗糙，充满工业气息。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T19:06:25+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/06 (643).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.536,"observed_resolution":"normal","observation_limits":[],"id":"VP-10804c2777cc8bac","origin":"visual"},{"work_id":"src-3327dfdd7035c32f","frame_id":"FG-7d4cf8af73e222e2","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/17 (656).jpg","source_page":"https://film-grab.com/2015/10/08/mad-max-2/","scene":"一名留着短发和络腮胡的男子，身穿深色翻领夹克，身体微侧，目光凝视左下方。背景是布满细碎鱼鳞状云层的广阔天空，占据了画面的绝大部分。","analysis":"采用低角度仰拍构图，人物位于画面右侧，仅可见头部及肩颈上半身，身体在画面下方被截断。背景天空云层密布，呈现出细碎的纹理，占据了约80%的画面空间。光线柔和，人物面部处于阴影中，轮廓在明亮天空的衬托下显得清晰，整体色调偏冷灰。","prompt":"低角度仰拍视角，画面右侧是一名留着深色短发和络腮胡的男子，身穿深色翻领夹克，身体微侧，目光凝视左下方。人物仅可见头部及肩颈上半身，身体在画面下方被截断。背景是布满细碎鱼鳞状云层的广阔天空，占据了画面的绝大部分。光线柔和，人物面部处于阴影中，轮廓在明亮天空的衬托下显得清晰，整体色调偏冷灰。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T19:06:32+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/17 (656).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.521,"observed_resolution":"normal","observation_limits":[],"id":"VP-5af982f6a0bc9f23","origin":"visual"},{"work_id":"src-3327dfdd7035c32f","frame_id":"FG-55008565adcdc37a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/28 (656).jpg","source_page":"https://film-grab.com/2015/10/08/mad-max-2/","scene":"画面右侧是一棵巨大的枯树，树干上有一个深黑色的圆形树洞。左侧是开阔的荒漠，地面呈浅褐色，散布着多棵枯树。远处有两个人影在树影间行走，背景是低矮的丘陵。","analysis":"构图采用前景大物体与远景人物的对比，右侧枯树占据画面约三分之一，形成视觉框架。人物位于画面中左部，全身可见，身形极小，与巨大的枯树形成强烈的大小反差。视角为平视，光线强烈，投射出长长的树影，明暗对比鲜明。色彩以土黄、灰褐为主，天空泛白，整体色调干燥、苍凉。","prompt":"这是一张横向宽幅的荒漠场景图。画面右侧前景是一棵巨大的枯树，树皮呈灰白色，树干上有一个巨大的圆形树洞，洞口深邃黑暗。左侧是开阔的浅褐色沙地，地面上散布着多棵枯死的树木，树干细长，枝条光秃。强烈的阳光从左侧照射，在地面投下长长的树影。在画面中左部的树影之间，有两个极小的人影正在行走，全身可见，身形渺小。背景是连绵的低矮丘陵，天空呈淡黄色，整体色调干燥、苍凉，呈现出一种荒凉、空旷的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T19:06:40+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/28 (656).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.524,"observed_resolution":"normal","observation_limits":[],"id":"VP-f0a3d3b152b94b37","origin":"visual"},{"work_id":"src-3327dfdd7035c32f","frame_id":"FG-ae1dab27d29f738e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/40 (653).jpg","source_page":"https://film-grab.com/2015/10/08/mad-max-2/","scene":"一名尖发人物站立在锈蚀金属结构顶端，背景是灰白天空与枯树，左侧有另一人物依附在倾斜的杆状物旁。","analysis":"仰视视角，主体人物全身可见，位于画面中央偏上，身形在灰白天空背景下呈剪影状。人物头顶有尖状突起，身着深色衣物，腿部有绑带。下方是粗糙的深色金属残骸，左侧有倾斜的长杆和另一模糊人影。光线平淡，整体色调灰暗，天空占据大部分画面，明暗对比不强。","prompt":"仰视视角，灰白阴沉的天空背景下，一名尖发人物站立在锈蚀金属结构顶端。人物全身可见，头顶有尖状突起，身着深色衣物，腿部有绑带，身形在天空背景下呈剪影状。下方是粗糙的深色金属残骸，左侧有倾斜的长杆和另一模糊人影。光线平淡，整体色调灰暗，天空占据大部分画面，明暗对比不强。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T19:06:48+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/40 (653).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.507,"observed_resolution":"normal","observation_limits":[],"id":"VP-30c23d392ec73b49","origin":"visual"},{"work_id":"src-3327dfdd7035c32f","frame_id":"FG-65ececf15cb73097","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/51 (626).jpg","source_page":"https://film-grab.com/2015/10/08/mad-max-2/","scene":"一名面部带血、神情惊恐的男子，身穿带有金属护肩和羽毛装饰的深色服装，身体前倾，双手向前伸出，背景是模糊的荒野丘陵。","analysis":"画面采用极近景构图，人物面部占据画面中心，视觉冲击力极强。人物上半身可见，头部和肩部被夸张的羽毛和金属装饰包围。镜头视角略微仰视，增强了人物的压迫感。光线为自然散射光，色彩以土黄、灰黑和暗红为主，背景虚化处理，突出了前景人物的细节和表情。","prompt":"这是一张写实风格的电影静帧，画面中心是一名表情极度惊恐的男子，他双眼圆睁，嘴巴大张，面部和额头布满暗红色的血迹，右眼下方有一道白色痕迹。他身穿深灰色粗布质感的服装，肩部装饰着巨大的黑色羽毛和银色金属护甲，胸前挂着一把小挂锁。他的双手戴着深色手套，向前伸出，似乎正抓着什么。前景下方有一根模糊的橙黄色横杆。背景是失焦的荒野，呈现出干燥的土黄色调，天空灰白。整体光线柔和，色彩饱和度适中，营造出一种紧张、怪诞且充满戏剧张力的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-10T19:06:56+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/51 (626).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.545,"observed_resolution":"normal","observation_limits":[],"id":"VP-53fc4ee039d0321f","origin":"visual"}]};